import{_ as a,o as e,c as i,a4 as n}from"./chunks/framework.BRzJ4ijD.js";const g=JSON.parse('{"title":"工程化实践轴 · 让代码真正跑进生产","description":"","frontmatter":{},"headers":[],"relativePath":"engineering/index.md","filePath":"engineering/README.md","lastUpdated":1788475713000}'),s={name:"engineering/index.md"};function r(l,t,o,d,p,h){return e(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="工程化实践轴-·-让代码真正跑进生产" tabindex="-1">工程化实践轴 · 让代码真正跑进生产 <a class="header-anchor" href="#工程化实践轴-·-让代码真正跑进生产" aria-label="Permalink to &quot;工程化实践轴 · 让代码真正跑进生产&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>前面 14 个部分（导论 / 数学 / 13 主题）讲的是**&quot;计算机是什么、为什么这样设计&quot;<strong>；这一轴补另一半——</strong>&quot;作为 1-20 年的工程师，你怎么把代码安全、可测、可发布、可观测、可维护地交到生产环境&quot;**。它不重复任何一部的原理（Git 讲透但不重讲 DSA），而是把工程师每天面对的手艺活系统化：版本控制、测试、CI/CD、性能工程、应用安全、代码质量、可观测性。</p><h2 id="思想链" tabindex="-1">思想链 <a class="header-anchor" href="#思想链" aria-label="Permalink to &quot;思想链&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[你写完了 feature 代码]</span></span>
<span class="line"><span>  └─&gt; Git 分支 + 提交规范 + code review</span></span>
<span class="line"><span>        └─&gt; CI 跑测试（单元/集成/契约/E2E）</span></span>
<span class="line"><span>              └─&gt; 构建产物 → 镜像 → 发布（蓝绿/金丝雀）</span></span>
<span class="line"><span>                    └─&gt; 上线后 metrics/logs/traces 三件套观测</span></span>
<span class="line"><span>                          └─&gt; 性能劣化 → profiling 定位 → 优化</span></span>
<span class="line"><span>                                └─&gt; 安全：OWASP + 认证授权 + 供应链</span></span>
<span class="line"><span>                                      └─&gt; 回头重构 → 代码质量维持</span></span>
<span class="line"><span>                                            └─&gt; 这就是工程化的完整闭环</span></span></code></pre></div><p>每一环都依赖前面 14 部分的原理（Git 基于 DAG/哈希、CI 基于 shell、性能基于组成原理的 cache/IO），但<strong>方法本身是独立的手艺</strong>——这正是&quot;工程化实践&quot;和&quot;计算机基础&quot;的互补关系。</p><h2 id="章节结构" tabindex="-1">章节结构 <a class="header-anchor" href="#章节结构" aria-label="Permalink to &quot;章节结构&quot;">​</a></h2><ul><li><a href="./">开篇: 工程化 = 让代码跑进生产的手艺</a> ← 当前</li><li><a href="./git-workflow">1. Git 与版本控制: 原理 / 分支模型 / 合并策略 / 进阶命令</a></li><li><a href="./testing">2. 测试工程: 测试金字塔 / 单元/集成/契约/E2E / mock / flaky 治理</a></li><li><a href="./cicd-devops">3. CI/CD 与发布工程: 管线 / 镜像 / 蓝绿金丝雀 / IaC</a></li><li><a href="./performance-engineering">4. 性能工程: profiling / 火焰图 / 缓存与批处理方法论</a></li><li><a href="./app-security">5. 应用安全: OWASP Top 10 / 认证授权 / 数据安全 / 供应链</a></li><li><a href="./code-quality">6. 代码质量: 重构 / code review / 复杂度治理 / DDD 落地</a></li><li><a href="./observability-practice">7. 可观测性实操: metrics/logs/traces 打点 / OpenTelemetry / SLO</a></li><li><a href="./gh-actions-deepdive">8. GitHub Actions 实战: workflow / expression / 缓存 / 矩阵 / reusable / 自托管</a></li><li><a href="./gitops-k8s">9. 云原生发布与 GitOps: K8s 应用 / Helm / ArgoCD / Flux / 服务网格</a></li><li><a href="./sre-engineering">10. SRE 工程: 错误预算 / 容量 / 变更 / 事件响应 / 生产就绪</a></li></ul><h2 id="与其余各部分的接口表" tabindex="-1">与其余各部分的接口表 <a class="header-anchor" href="#与其余各部分的接口表" aria-label="Permalink to &quot;与其余各部分的接口表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>本轴章节</th><th>依赖的原理部分</th><th>互补关系</th></tr></thead><tbody><tr><td>Git 工作流</td><td>分布式 §时钟/DAG、DSA §哈希表</td><td>Git 是&quot;内容寻址 DAG&quot;的具体实例</td></tr><tr><td>测试工程</td><td>编译 §语义分析、数学 §逻辑</td><td>测试 = 可验证性工程化（README 定位&quot;可被验证&quot;落地）</td></tr><tr><td>CI/CD</td><td>OS §shell/进程、网络 §HTTP、分布式 §一致性</td><td>发布 = 状态机 + 幂等 + 原子切换</td></tr><tr><td>性能工程</td><td>组成原理 §cache/IO/流水线、OS §调度/内存</td><td>profiling = 把性能归因到硬件层</td></tr><tr><td>应用安全</td><td>密码学 §侧信道/TLS、网络 §HTTP/TLS</td><td>OWASP 是&quot;应用层&quot;的密码学落地</td></tr><tr><td>代码质量</td><td>编译 §AST/复杂度、理论 §可判定性</td><td>重构 = 保持行为的语义等价变换</td></tr><tr><td>可观测性</td><td>系统设计 §monitor/SLO、分布式 §故障模型</td><td>三件套 = 分布式调试的基础设施</td></tr></tbody></table><h2 id="这轴不是什么" tabindex="-1">这轴不是什么 <a class="header-anchor" href="#这轴不是什么" aria-label="Permalink to &quot;这轴不是什么&quot;">​</a></h2><ul><li><strong>不是</strong>重复原理章节（不重讲 B+树 / TCP / 哈希）。它假设你已经会，讲的是<strong>怎么用、怎么落地、怎么诊断</strong>。</li><li><strong>不是</strong>某一门语言的教程（不教 Go 语法）。例子用 Go/Python/TS 等，但方法通用。</li><li><strong>不是</strong>工程管理/软技能（不谈绩效、团队协作）。</li><li><strong>不是</strong>某一家云厂商/单一平台的完整文档（GitHub Actions / K8s 为实例，但方法论通用）。</li></ul><h2 id="阅读路径" tabindex="-1">阅读路径 <a class="header-anchor" href="#阅读路径" aria-label="Permalink to &quot;阅读路径&quot;">​</a></h2><ul><li><strong>1-5 年工程师</strong>：§1 Git → §2 测试 → §3 CI/CD → §8 GitHub Actions → §5 应用安全（先建立规范直觉）</li><li><strong>5-15 年工程师</strong>：§4 性能 → §6 代码质量 → §7 可观测性 → §9 GitOps → §10 SRE（深入到方法学）</li><li><strong>想横通</strong>：按 <code>Git → 测试 → CI/CD → Actions → 发布/GitOps → 可观测 → 性能 → 安全 → 重构 → SRE</code> 的交付闭环顺序走</li></ul><hr><p>下一篇: <a href="./git-workflow">1. Git 与版本控制: 原理 / 分支模型 / 合并策略 / 进阶命令</a>.</p>`,16)])])}const u=a(s,[["render",r]]);export{g as __pageData,u as default};
